  function meal(){return state.recipes.find(function(r){return r.id===meals[today]&&hiddenRecipes.indexOf(r.id)<0;})||null;}
  function nextAppointment(){var b=HubTools.brief(eventsOn(today),tasks(),new Date(),today),e=b.next;return e?'<span class="eyebrow">'+(b.ongoing?'En cours':'Prochain rendez-vous')+'</span><h2>'+esc(e.title)+'</h2><p class="brief-time">'+esc(e.start)+' — '+esc(e.end)+'</p><p>'+esc(sourceStyles[e.source].name)+'</p>': '<span class="eyebrow">Du temps devant soi</span><h2>Pas d’autre rendez-vous prévu.</h2><p>Profite de cette respiration dans la journée.</p>';}
  function briefPage(){var b=HubTools.brief(eventsOn(today),tasks(),new Date(),today),r=meal(),w=state.weather;return title('Bonjour, la journée.','Ce qui compte aujourd’hui, sans tout parcourir.',action('nav:home',icon('left')+'Maison','pill'))+'<div class="brief-grid"><section class="card brief-next"><div data-brief-next>'+nextAppointment()+'</div><div class="brief-bottom"><small>'+(calendarConnected()?calendarLabel():state.demo?'Agenda · exemples':'Agenda à connecter')+'</small>'+action('nav:calendar','Voir l’agenda '+icon('arrow'),'pill')+'</div></section><section class="card brief-weather"><span class="eyebrow">Dehors</span><h2>'+(w?Math.round(w.temperature)+'°':state.demo?'14°':'—')+'</h2><p>'+(w?esc(w.city)+' · '+esc(w.summary):state.demo?'Quelques éclaircies · exemple':'Choisis la météo de chez toi.')+'</p><small>'+(w?'Relevé du '+esc(weatherStamp(w)):'')+'</small>'+action('settings',icon('pin')+'Choisir la ville','pill')+'</section><section class="card brief-tasks"><span class="eyebrow">Trois priorités, au plus</span><h2>L’essentiel du jour.</h2><div class="task-list">'+(b.priorities.length?b.priorities.map(taskRow).join(''):'<p class="brief-empty">Les tâches du jour sont terminées.</p>')+'</div><small>'+(todoistConnected()?'Todoist connecté':state.demo?'Tâches · exemples et ajouts locaux':'Tâches de cet appareil')+'</small>'+action('nav:tasks','Toutes les tâches '+icon('arrow'),'pill')+'</section><section class="card brief-meal"><span class="eyebrow">À table, ce soir</span><h2>'+(r?esc(r.title):'Un repas à prévoir.')+'</h2><p>'+(r?esc(r.subtitle)+' · '+r.time+' min':'Choisis une recette dans ton carnet.')+'</p><label for="brief-meal">Le repas d’aujourd’hui</label><select id="brief-meal"><option value="">Aucun repas choisi</option>'+state.recipes.filter(function(x){return hiddenRecipes.indexOf(x.id)<0;}).map(function(x){return '<option value="'+esc(x.id)+'" '+(r&&r.id===x.id?'selected':'')+'>'+esc(x.title)+'</option>';}).join('')+'</select>'+(r?action('recipe:'+esc(r.id),icon('kitchen')+'On cuisine','pill primary'):action('nav:kitchen',icon('book')+'Explorer les recettes','pill'))+'</section></div><div class="brief-shortcuts">'+action('timer-panel',icon('timer')+'Un minuteur','pill')+action('nav:companion',icon('smartphone')+'À garder sur le cadre','pill')+action('nav:links',icon('link')+'Mes liens de recettes','pill')+'</div>';}
  function timerPanel(){var t=state.timer,left=HubTools.remaining(t,Date.now()),label=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');return '<div class="timer-panel"><span class="eyebrow">Un minuteur, depuis chaque écran</span><div class="timer-display" data-timer-display>'+(t?left?label:'Minuteur terminé':'00:00')+'</div><p data-timer-status>'+(t?left===0?'C’est prêt.':t.paused?'En pause':esc(t.label||'En cours'):'Choisis une durée.')+'</p>'+(t?'<div class="timer-actions">'+(left?action('timer-toggle',icon(t.paused?'play':'pause')+(t.paused?'Reprendre':'Pause'),'pill primary'):'')+action('timer-add','+ 1 minute','pill')+action('timer-stop',icon('close')+'Terminer','pill')+'</div>':'<div class="timer-presets">'+[3,5,10,25].map(function(n){return action('timer-preset:'+n,n+' min','pill');}).join('')+'</div><form id="timer-form" class="local-form"><label for="timer-label">Pour quoi ?</label><input id="timer-label" name="label" maxlength="80" placeholder="Pâtes, thé, pause…"><div class="duration-fields"><label>Minutes<input name="minutes" type="number" min="0" max="1440" value="5" required></label><label>Secondes<input name="seconds" type="number" min="0" max="59" value="0" required></label></div><button class="pill primary">'+icon('play')+'Lancer le minuteur</button><p id="timer-error" role="alert"></p></form>')+'<p class="timer-note">Le minuteur reste visible pendant la navigation. Il reprend après rechargement. Le signal est visuel : garde le cadre ouvert pour le voir arriver à zéro.</p></div>';}
  function startTimer(seconds,label){if(!Number.isInteger(seconds)||seconds<1||seconds>86400)throw new Error('Choisis une durée entre 1 seconde et 24 heures.');if(state.timer&&(state.timer.paused||HubTools.remaining(state.timer,Date.now())>0)){toast('Un minuteur est déjà en cours. Termine-le avant d’en lancer un autre.');return;}state.timer={end:Date.now()+seconds*1000,label:String(label||'Minuteur').slice(0,80),paused:false};save('timer',state.timer);renderTimer();scheduleTick();if(state.modal==='timer')renderOverlay();toast('Minuteur lancé.');}
  function keptCard(x){var body=x.kind==='note'?'<p class="kept-note">'+esc(x.text)+'</p>':x.kind==='photo'?action('kept-photo:'+x.id,'<img loading="lazy" alt="'+esc(x.title)+'" src="'+x.image+'">','kept-photo-button'):x.kind==='link'?'<a class="pill" target="_blank" rel="noopener noreferrer" href="'+esc(x.url)+'">'+icon('external-link')+'Ouvrir la recette</a>':'<p>'+x.time+' min · '+x.servings+' personne'+(x.servings===1?'':'s')+'</p>'+action('kept-recipe:'+x.id,icon('plus')+'Ajouter au carnet','pill')+(x.url?'<a class="kept-source" target="_blank" rel="noopener noreferrer" href="'+esc(x.url)+'">Lire la source ↗</a>':'');return '<article class="card kept-card"><span class="eyebrow">'+({note:'Une note',photo:'Une photo',recipe:'Une recette',link:'Un lien'}[x.kind])+'</span><h2>'+esc(x.title)+'</h2>'+body+'</article>';}
  function companionPage(){return title('À garder.','Des idées sur le téléphone, à retrouver sur le cadre.',action('nav:home',icon('left')+'Maison','pill'))+'<div class="local-banner"><div>'+icon('smartphone')+'<h2>Un transfert, sans serveur.</h2><p>Prépare ton contenu ici, puis exporte le fichier. Transfère-le sur le cadre par le moyen de ton choix, et importe-le. Chaque appareil garde sa propre copie ; rien n’est envoyé automatiquement.</p></div><div class="local-transfer-actions">'+action('kept-export',icon('upload')+'Exporter le fichier','pill primary',kept.length?'':'disabled')+'<label class="pill local-file">'+icon('plus')+'Importer un fichier<input id="kept-import" type="file" accept="application/json,.json" aria-label="Fichier de transfert Hub."></label><small>'+kept.length+' contenu'+(kept.length===1?'':'s')+' sur cet appareil</small></div></div>'+('<p role="alert" class="local-error" data-kept-error '+(keptError?'':'hidden')+'>'+esc(keptError)+'</p>')+'<div class="companion-layout"><section class="card"><h2>Une chose à garder.</h2><form id="kept-form" class="local-form"><label for="kept-kind">Contenu</label><select id="kept-kind" name="kind">'+[['note','Une note'],['photo','Une photo'],['link','Un lien de recette'],['recipe','Une recette complète']].map(function(a){return '<option value="'+a[0]+'" '+(draftKind===a[0]?'selected':'')+'>'+a[1]+'</option>';}).join('')+'</select><label for="kept-title">Titre</label><input id="kept-title" name="title" required maxlength="160" placeholder="Une idée à ne pas oublier"><div data-kept-type="note" '+(draftKind!=='note'?'hidden':'')+'><label for="kept-text">La note</label><textarea id="kept-text" name="text" maxlength="20000" placeholder="Quelques mots pour la maison…"></textarea></div><div data-kept-type="photo" '+(draftKind!=='photo'?'hidden':'')+'><label for="kept-photo">La photo</label><input id="kept-photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG ou WebP · 12 Mo maximum. La photo sera préparée pour le cadre, sans métadonnées.</small></div><div data-kept-type="link recipe" '+(!['link','recipe'].includes(draftKind)?'hidden':'')+'><label for="kept-url">Lien du site'+(draftKind==='recipe'?' · facultatif':'')+'</label><input id="kept-url" name="url" type="url" maxlength="2048" placeholder="https://…"></div><div data-kept-type="recipe" '+(draftKind!=='recipe'?'hidden':'')+'><label for="kept-ingredients">Ingrédients · un par ligne</label><textarea id="kept-ingredients" name="ingredients" maxlength="16000"></textarea><label for="kept-steps">Étapes · une par ligne</label><textarea id="kept-steps" name="steps" maxlength="16000"></textarea><div class="duration-fields"><label>Minutes<input name="time" type="number" min="1" max="1440" value="30"></label><label>Personnes<input name="servings" type="number" min="1" max="20" value="2"></label></div></div><button class="pill primary" '+(companionBusy?'disabled':'')+'>'+icon('plus')+'Garder sur cet appareil</button><p id="kept-message" role="status"></p></form></section><div><div class="kept-heading"><h2>Sur cet appareil</h2><small>Le fichier exporté contient ces éléments.</small></div><div class="kept-grid">'+(kept.length?kept.slice().reverse().map(keptCard).join(''):'<div class="card empty-state">'+icon('book')+'Ta collection attend sa première idée.</div>')+'</div></div></div>';}
  function linksPage(){var links=kept.filter(function(x){return x.kind==='link'||x.kind==='recipe'&&x.url;});return title('Les recettes du web.','Tes liens gardés, pour retrouver la page d’origine.',action('nav:kitchen',icon('left')+'Le carnet','pill'))+'<section class="card link-intro"><h2>La page d’origine, à portée de main.</h2><p>Les liens s’ouvrent dans un nouvel onglet. Ferme cet onglet pour revenir au cadre et retrouver ton minuteur. Pour cuisiner sans publicité ni distractions, garde plutôt les étapes dans le carnet.</p><form id="recipe-link-form" class="local-form"><label for="link-title">Nom de la recette</label><input id="link-title" name="title" maxlength="160" required placeholder="La tarte qu’on veut essayer"><label for="link-url">Adresse du site</label><input id="link-url" name="url" type="url" required maxlength="2048" placeholder="https://…"><button class="pill primary">'+icon('plus')+'Garder ce lien</button><p id="link-error" role="alert"></p></form></section><div class="kept-grid link-grid">'+links.map(keptCard).join('')+'</div>';}
  function updateKeptCollection(){
    if(!['companion','links'].includes(state.page))return;
    var grid=$('.kept-grid');if(grid){var list=state.page==='links'?kept.filter(function(x){return x.kind==='link'||x.kind==='recipe'&&x.url;}):kept.slice().reverse();grid.innerHTML=list.length?list.map(keptCard).join(''):state.page==='companion'?'<div class="card empty-state">'+icon('book')+'Ta collection attend sa première idée.</div>':'';}
    var count=$('.local-transfer-actions small'),button=$('[data-action="kept-export"]'),error=$('[data-kept-error]');
    if(count)count.textContent=kept.length+' contenu'+(kept.length===1?'':'s')+' sur cet appareil';if(button)button.disabled=!kept.length;
    if(error){error.textContent=keptError;error.hidden=!keptError;}else if(keptError&&$('#link-error'))$('#link-error').textContent=keptError;
  }
  async function loadKept(){try{kept=await HubTools.entries();keptError='';}catch(e){keptError=e.message;}updateKeptCollection();}
  function formSnapshot(form){return Array.from(form.elements).map(function(input){return input.type==='file'?Array.from(input.files):input.value;});}
  function resetSavedForm(form,snapshot){var current=formSnapshot(form);if(current.length!==snapshot.length||current.some(function(value,i){return Array.isArray(value)?value.length!==snapshot[i].length||value.some(function(file,n){return file!==snapshot[i][n];}):value!==snapshot[i];}))return;form.reset();if(form.id==='kept-form'){form.elements.kind.value=draftKind;updateKeptFields();}}
  function exportKept(items){var packet=HubTools.transfer({format:'hub-transfer',version:1,items:items}),blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hub-transfert-'+today+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);}
  function importKeptRecipe(entry){var r=normalizeRecipe({'@type':'Recipe',name:entry.title,recipeIngredient:entry.ingredients.split('\n').filter(Boolean),recipeInstructions:entry.steps.split('\n').filter(Boolean),totalTime:'PT'+entry.time+'M',recipeYield:entry.servings,url:entry.url||'Transfert local'});r.id='import-shared-'+entry.id;if(state.recipes.some(function(x){return x.id===r.id;})){toast('Cette recette est déjà dans ton carnet.');return;}var next=state.recipes.concat(r);localStorage.setItem('hub.recipes',JSON.stringify(next.filter(function(x){return x.id.indexOf('import-')===0;})));state.recipes=next;toast('Recette ajoutée au carnet.');}

  function updateKeptFields(){document.querySelectorAll('[data-kept-type]').forEach(function(el){el.querySelectorAll('input,textarea').forEach(function(input){input.disabled=el.hidden;});});}
  async function submitKept(form){if(companionBusy)return;companionBusy=true;var button=form.querySelector('button'),message=$('#kept-message'),snapshot=formSnapshot(form);button.disabled=true;message.textContent='Préparation…';try{var kind=form.elements.kind.value,raw={id:HubTools.id(),kind:kind,title:form.elements.title.value};if(kind==='note')raw.text=form.elements.text.value;if(kind==='photo')raw.image=await HubTools.photo(form.elements.photo.files[0]);if(kind==='link'||kind==='recipe')raw.url=form.elements.url.value;if(kind==='recipe'){raw.ingredients=form.elements.ingredients.value;raw.steps=form.elements.steps.value;raw.time=Number(form.elements.time.value);raw.servings=Number(form.elements.servings.value);}await HubTools.store([HubTools.item(raw)]);resetSavedForm(form,snapshot);message.textContent='Contenu enregistré.';companionBusy=false;await loadKept();toast('Contenu enregistré sur cet appareil.');}catch(e){message.textContent=e.message;}finally{companionBusy=false;if(button.isConnected)button.disabled=false;}}
  async function importTransferFile(input){var file=input.files[0];if(!file)return;input.disabled=true;try{if(file.size>10000000)throw new Error('Le fichier doit faire moins de 10 Mo.');var packet=HubTools.transfer(await file.text()),count=await HubTools.store(packet.items);await loadKept();toast(count?count+' contenu'+(count===1?' importé.':'s importés.'):'Ces contenus sont déjà présents.');}catch(e){keptError=e.message;updateKeptCollection();}finally{input.disabled=false;input.value='';}}

