  var spotifyPairCode='',spotify=HubConnect.spotify({}),music={data:null,error:'',busy:false,updated:0,devices:[],devicesBusy:false,devicesError:''},servicesTick;
  var lyricsClient=HubLyrics.create(),lyricsState={open:false,busy:false,result:null,error:'',key:'',revision:0,line:-2},lyricsTick,lyricsAuto=read('lyricsAuto',true),lyricsAttemptedKey='',lyricsHiddenKeys=new Set();
  function musicTrackKey(){var t=music.data&&music.data.item;return t?JSON.stringify([t.id||'',t.name,t.artists&&t.artists[0]&&t.artists[0].name,t.album&&t.album.name,t.duration_ms]):'';}
  function musicProgress(){var p=music.data,t=p&&p.item;return Math.min(Number(t&&t.duration_ms)||0,Math.max(0,(Number(p&&p.progress_ms)||0)+(p&&p.is_playing?Math.max(0,Date.now()-music.updated):0)));}
