  function serviceRender(force){if(!['home','shopping','music'].includes(state.page))return;mainDirty=true;if(state.modal||state.sleep||/^(INPUT|SELECT|TEXTAREA)$/.test(document.activeElement.tagName)||!force&&inputMode==='keyboard'&&document.activeElement.tagName==='BUTTON'&&state.page!=='music')return;if(['home','shopping','music'].includes(state.page))render();}
  async function refreshShopping(){if(!shop.client||!shop.project||shop.busy||document.hidden||shop.retryAt>Date.now())return;var client=shop.client,project=shop.project;shop.busy=true;try{var results=await Promise.all([client.sections(project),client.tasks(project)]);if(client!==shop.client||project!==shop.project)return;shop.sections=results[0];shop.active=results[1];shop.loaded=true;shop.updated=Date.now();shop.retryAt=0;shop.error='';try{var completed=await client.completed(project);if(client===shop.client&&project===shop.project){shop.completed=completed;shop.historyError='';}}catch(e){if(client===shop.client&&project===shop.project)shop.historyError='Historique indisponible. Les achats actifs restent accessibles.';}}catch(e){if(client===shop.client&&project===shop.project){shop.error=e.message;shop.retryAt=Date.now()+(e.retryAfter||60000);}}finally{shop.busy=false;serviceRender();if(shop.client&&(client!==shop.client||project!==shop.project))refreshShopping();}}
