  function shoppingConfig(){return '<p>Le cadre communique directement avec Todoist. Aucun serveur personnel nécessaire. Un seul compte, deux listes séparées : les achats restent dans le projet choisi, les tâches du jour et en retard excluent ce projet et ses sous-projets.</p><form id="todoist-session-form" class="local-form"><label for="todoist-token">Jeton API Todoist</label><input id="todoist-token" name="token" type="password" autocomplete="off" required placeholder="Coller le jeton depuis Todoist"><label class="setting-line"><span>Rester connecté sur cet appareil</span><input name="remember" type="checkbox" '+(localStorage.getItem('hub.todoist.token')?'checked':'')+'></label><button class="pill primary">Charger mes projets</button></form><p class="service-error" role="alert">'+esc(shop.error)+'</p>'+(shop.client?'<form id="shopping-project-form" class="local-form"><label for="shopping-project">Projet utilisé pour les courses</label><select id="shopping-project" name="project" required><option value="">Choisir un projet</option>'+shop.projects.map(function(p){return '<option value="'+esc(p.id)+'" '+(shop.project===p.id?'selected':'')+'>'+esc(p.name)+'</option>';}).join('')+'</select><button class="pill primary">Utiliser ce projet</button></form><div class="setting-shortcuts">'+action('shopping-create','Créer le projet course','pill')+action('shopping-sections','Créer les rayons manquants','pill',shop.project?'':'disabled')+action('shopping-disconnect','Déconnecter Todoist','pill')+'</div>':'')+'<div class="note"><p>Le jeton donne accès à ton compte Todoist. Il est envoyé uniquement à l’API officielle de Todoist. Pour une liste partagée, partage le projet depuis l’application Todoist. Aucun achat local n’est envoyé sans ton action.</p></div>';}
