  function paintMusicColors(){if(state.page!=='music'||state.sleep||document.hidden)return;var url=musicPaletteURL(),screen=$('.music-screen');if(!url||!screen)return;var colors=musicPalettes.get(url);if(colors){screen.style.setProperty('--music-tone-a',colors.a);screen.style.setProperty('--music-tone-b',colors.b);return;}if(musicPaletteLoading===url)return;musicPaletteLoading=url;var image=new Image();image.crossOrigin='anonymous';image.referrerPolicy='no-referrer';image.onload=function(){try{var canvas=document.createElement('canvas');canvas.width=24;canvas.height=24;var context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,24,24);musicPalettes.set(url,HubMusicColors.palette(context.getImageData(0,0,24,24).data));while(musicPalettes.size>8)musicPalettes.delete(musicPalettes.keys().next().value);}catch(_){musicPalettes.set(url,HubMusicColors.palette([]));}finally{if(musicPaletteLoading===url)musicPaletteLoading='';if(musicPaletteURL()===url)paintMusicColors();}};image.onerror=function(){musicPalettes.set(url,HubMusicColors.palette([]));if(musicPaletteLoading===url)musicPaletteLoading='';};image.src=url;}
