    if(id==='calendar-import-form'||id==='connections-import-form'){var button=form.querySelector('button');button.disabled=true;try{if(id==='calendar-import-form'){var list=[];for(var file of form.elements.files.files){if(file.size>10000000)throw Error('Fichier trop volumineux.');list.push({source:form.elements.source.value,text:await file.text()});}var prepared=prepareCalendars(list),replacement=form.elements.replace.value;if(replacement){if(prepared.length!==1)throw Error('Choisis un seul fichier pour remplacer cet agenda.');var old=calendarImports.find(function(c){return c.id===replacement;});prepared[0].id=replacement;if(old){prepared[0].name=old.name;prepared[0].source=old.source;}}mergeCalendars(prepared);}else{var file=form.elements.file.files[0];if(!file||file.size>18000000)throw Error('Fichier invalide.');var bundle=await HubConnectionBundle.open(JSON.parse(await file.text()),form.elements.code.value.trim()),prepared=prepareCalendars(bundle.calendars),githubSnapshot=bundle.github?HubGithub.snapshot(bundle.github,state.githubUser):null,client=null,projects=[];if(bundle.todoist){client=HubConnect.todoist(bundle.todoist.token);projects=await client.projects();if(!projects.some(function(p){return p.id===bundle.todoist.project;}))throw Error('Projet de courses introuvable.');}mergeCalendars(prepared);if(client){(form.elements.remember.checked?localStorage:sessionStorage).setItem('hub.todoist.token',bundle.todoist.token);(form.elements.remember.checked?sessionStorage:localStorage).removeItem('hub.todoist.token');shop.token=bundle.todoist.token;shop.client=client;shop.projects=projects;shop.project=bundle.todoist.project;save('shoppingProject',shop.project);shop.loaded=false;shop.error='';shop.retryAt=0;daily.loaded=false;daily.retryAt=0;state.shoppingMode='todoist';save('shoppingMode','todoist');scheduleServices();refreshShopping();refreshDaily();}if(githubSnapshot){state.github=githubSnapshot;save('github',state.github);}if(bundle.homeAssistant){await houseStart(bundle.homeAssistant.url,bundle.homeAssistant.token,form.elements.remember.checked);if(house.status!=='connected')throw Error(house.error||'Connexion Home Assistant impossible.');}form.elements.code.value='';}closeModal();render();toast('Connexions importées sur cet appareil.');}catch(e){form.querySelector('[data-import-error]').textContent=e.message;}finally{if(button.isConnected)button.disabled=false;}return true;}

    if(id==='spotify-link-export'){var button=form.querySelector('button');button.disabled=true;try{var association=await HubSpotifyLink.encrypt(spotify.exportToken());spotifyPairCode=association.code;renderOverlay();var blob=new Blob([JSON.stringify(association.packet)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='hub-spotify-link.json';document.body.appendChild(link);link.click();link.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);}catch(err){var error=form.querySelector('[role=alert]');if(error)error.textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}return true;}
    if(id==='spotify-link-import'){var button=form.querySelector('button');button.disabled=true;try{var file=form.elements.file.files[0];if(!file||file.size>25000)throw Error('Choisis un fichier d’association Hub valide.');var session=await HubSpotifyLink.decrypt(JSON.parse(await file.text()),form.elements.secret.value.trim());spotify.importToken(session,form.elements.remember.checked);save('spotifyClient',session.client_id);form.elements.secret.value='';closeModal();state.page='music';state.recipeId=null;render();scheduleServices();await refreshMusic(true);toast('Spotify associé à cet appareil.');}catch(err){var error=form.querySelector('[role=alert]');if(error)error.textContent=err instanceof SyntaxError?'Ce fichier d’association est invalide.':err.message;}finally{if(button.isConnected)button.disabled=false;}return true;}

    if(id==='todoist-session-form'){form.querySelector('button').disabled=true;var token=form.elements.token.value.trim();form.elements.token.value='';try{var client=HubConnect.todoist(token),projects=await client.projects();(form.elements.remember.checked?localStorage:sessionStorage).setItem('hub.todoist.token',token);(form.elements.remember.checked?sessionStorage:localStorage).removeItem('hub.todoist.token');shop.token=token;shop.client=client;shop.projects=projects;shop.error='';shop.retryAt=0;daily.loaded=false;daily.retryAt=0;scheduleServices();refreshDaily();shop.loaded=false;shop.active=[];shop.completed=[];if(!projects.some(function(p){return p.id===shop.project;}))shop.project='';renderOverlay();}catch(e){shop.error=e.message;renderOverlay();}return true;}
    if(id==='shopping-project-form'){if(shop.busy)throw new Error('Patiente pendant l’actualisation.');var project=form.elements.project.value;if(!shop.projects.some(function(p){return p.id===project;}))throw new Error('Choisis un projet valide.');shop.project=project;shop.loaded=false;shop.active=[];shop.completed=[];save('shoppingProject',project);state.shoppingMode='todoist';save('shoppingMode','todoist');closeModal();state.page='shopping';state.recipeId=null;render();await refreshShopping();await refreshDaily();return true;}
    if(id==='purchase-form'){var label=form.elements.label.value.trim(),category=form.elements.category.value;if(!label)return true;var button=form.querySelector('button');button.disabled=true;try{if(state.shoppingMode==='todoist'){await shoppingWrite(function(){return shop.client.add(shop.project,label,category,'Ajouté depuis Hub.');});await refreshShopping();}else{var next=state.shopping.concat({key:'manual:'+Date.now(),label:label,category:category||HubConnect.category(label),recipe:'À ne pas oublier',done:false});localStorage.setItem('hub.shopping',JSON.stringify(next));state.shopping=next;}render();$('#purchase-label').focus();}catch(e){toast(e.message);}finally{if(button.isConnected)button.disabled=false;}return true;}
    if(id==='purchase-edit-form'){var label=form.elements.label.value.trim(),category=form.elements.category.value,button=form.querySelector('button');button.disabled=true;try{if(state.shoppingMode==='todoist'){await shoppingWrite(async function(){await shop.client.update(shopEdit,{content:label});await shop.client.move(shopEdit,shop.project,category);});await refreshShopping();}else{var next=state.shopping.map(function(x,i){return String(i)===shopEdit?Object.assign({},x,{label:label,category:category}):x;});localStorage.setItem('hub.shopping',JSON.stringify(next));state.shopping=next;}closeModal();render();}catch(e){$('#purchase-edit-error').textContent=e.message;}finally{if(button.isConnected)button.disabled=false;}return true;}
    if(id==='spotify-connect-form'){var client=form.elements.client.value.trim();save('spotifyClient',client);try{spotify.remember(form.elements.remember.checked);await spotify.authorize(client);}catch(e){$('#spotify-error').textContent=e.message;}return true;}
    return false;
